const ARRIVAL_STATEMENTS: Record<string, { kind: "log" | "set"; add_sql: string; del_sql: string | null }> = {
  __host_response_fetch: { kind: "set", add_sql: `INSERT INTO "__host_response_fetch" ("witness_digest", "ordinal", "ep", "prev", "status", "tag", "stars", "full_name") VALUES (?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT ("witness_digest", "ordinal") DO UPDATE SET "ep" = excluded."ep", "prev" = excluded."prev", "status" = excluded."status", "tag" = excluded."tag", "stars" = excluded."stars", "full_name" = excluded."full_name"`, del_sql: `DELETE FROM "__host_response_fetch" WHERE "witness_digest" = ? AND "ordinal" = ? AND "ep" = ? AND "prev" = ? AND "status" = ? AND "tag" = ? AND "stars" = ? AND "full_name" = ?` },
  etag_event: { kind: "log", add_sql: `INSERT INTO "etag_event" ("ep", "tag") VALUES (?, ?)`, del_sql: null },
  interval: { kind: "set", add_sql: `INSERT OR IGNORE INTO "interval" ("period", "bucket") VALUES (?, ?)`, del_sql: `DELETE FROM "interval" WHERE "period" = ? AND "bucket" = ?` },
  watch: { kind: "set", add_sql: `INSERT OR IGNORE INTO "watch" ("ep") VALUES (?)`, del_sql: `DELETE FROM "watch" WHERE "ep" = ?` },
};

function arrival_statement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`0_ghcacher_clock_golden: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`0_ghcacher_clock_golden: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.del_sql === null) {
      throw new Error(`0_ghcacher_clock_golden: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.del_sql, args: bind_args(arrival.row) };
  }
  return { sql: template.add_sql, args: bind_args(arrival.row) };
}

function apply_arrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrival_statement);
  return seam.runner.batch(seam.db, statements);
}

